$ cat Huge.java
public class Huge {
    public static void main(String[] a) {
        int kb = Integer.parseInt(a[0]);
        Deque<byte[]> q = new ArrayDeque<>();
        for (int i = 0; i < 4000; i++) {
            q.add(new byte[kb * 1024]);
            if (q.size() > 20) q.poll();      // 금방 버린다
        }
    }
}

# 리전 1MB 이므로 경계는 512KB

